// Daily Wisdom - 365 Stoic quotes for year-round daily rotation
// Inspired by The Daily Stoic by Ryan Holiday

export type StoicAuthor = "Marcus Aurelius" | "Seneca" | "Epictetus" | "Musonius Rufus" | "Cato" | "Zeno";
export type StoicVirtue = "courage" | "temperance" | "justice" | "wisdom";

export interface DailyWisdom {
  dayOfYear: number;           // 1-366
  quote: string;
  author: StoicAuthor;
  virtue: StoicVirtue;
  theme?: string;              // e.g., "control", "adversity", "time"
  source?: string;             // e.g., "Meditations 4.3"
}

// Helper to get day of year (1-366)
export function getDayOfYear(date: Date = new Date()): number {
  const start = new Date(date.getFullYear(), 0, 0);
  const diff = date.getTime() - start.getTime();
  const oneDay = 1000 * 60 * 60 * 24;
  return Math.floor(diff / oneDay);
}

// Helper to get date string for consistent caching
export function getDateString(date: Date = new Date()): string {
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
}

