// Get quote by day of year
export function getWisdomByDay(dayOfYear: number): DailyWisdom {
  // Handle leap year and edge cases
  const index = ((dayOfYear - 1) % 366 + 366) % 366;
  return dailyWisdomEntries[index] || dailyWisdomEntries[0];
}

// Get today's wisdom
export function getTodaysWisdom(): DailyWisdom {
  const today = getDayOfYear();
  return getWisdomByDay(today);
}

// Get wisdoms by virtue (for personalization)
export function getWisdomsByVirtue(virtue: StoicVirtue): DailyWisdom[] {
  return dailyWisdomEntries.filter(w => w.virtue === virtue);
}

// Get a random wisdom for a specific virtue (for virtue boosting)
export function getRandomWisdomForVirtue(virtue: StoicVirtue): DailyWisdom {
  const wisdoms = getWisdomsByVirtue(virtue);
  return wisdoms[Math.floor(Math.random() * wisdoms.length)];
}

// Legacy exports for backwards compatibility with existing code
export const stoicQuotes = dailyWisdomEntries.slice(0, 12).map(w => ({
  text: w.quote,
  author: w.author,
}));

export const WISDOM_CARDS = dailyWisdomEntries.slice(0, 12).map(w => ({
  quote: w.quote,
  author: w.author,
}));
